style.css:
@-moz-document domain("pinterest.com") {
/* Backgrounds */
  body,
  html,
  div,
  section,
  .appContent,
  .Jea,
  .Yl-,
  .Pj7 {
    background-color: #16080B !important;
    color: #F6E8EA !important;
  }

  /* Pins & cards */
  .GrowthUnauthPinImage,
  .pinWrapper,
  .gridItem,
  .Pin,
  .pinHolder,
  .pinImageWrapper {
    background-color: #1E0D10 !important;
    border-radius: 12px !important;
    border: 1px solid #5C3A3E !important;
  }

  /* Text */
  p,
  span,
  h1, h2, h3, h4, h5, h6,
  .tBJ,
  .title,
  .text,
  .pinDescription {
    color: #F6E8EA !important;
  }

  /* Links and hover effects */
  a,
  button,
  .Button,
  .link,
  .btn {
    color: #A93A4C !important;
    transition: 0.3s ease;
  }

  a:hover,
  button:hover,
  .Button:hover,
  .link:hover,
  .btn:hover {
    color: #FF7E8A !important;
  }

  /* Header and navigation */
  header,
  .Header,
  .RCK,
  .appHeader {
    background-color: #1A0A0D !important;
    color: #F6E8EA !important;
    border-bottom: 1px solid #5C3A3E !important;
  }

  /* Search bar */
  input[type="text"],
  input,
  textarea {
    background-color: #2A0F13 !important;
    color: #F6E8EA !important;
    border: 1px solid #5C3A3E !important;
  }

  /* Buttons */
  .btn-primary,
  .SignupButton,
  .SaveButton {
    background-color: #7A1F33 !important;
    color: #F6E8EA !important;
    border: none !important;
  }

  .btn-primary:hover,
  .SignupButton:hover,
  .SaveButton:hover {
    background-color: #A93A4C !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #16080B;
  }
  ::-webkit-scrollbar-thumb {
    background-color: #7A1F33;
    border-radius: 10px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background-color: #A93A4C;
  }
}
